'use strict';

/*
 * The vault settings reference page (docs/reference/vault-config.md) matches the code. Its two
 * tables are generated by scripts/docs-reference.js from the panel's key lists, the pin's defaults,
 * the scaffold and the validator; this file holds the literal expectations on the facts the
 * generator reads, units on scratch inputs, the two-way scan of the source for the keys read from
 * vault.config.json, and checks that the page's examples are valid.
 *
 * Tests that pass today and so prove nothing on their own (their evidence is the recorded mutation
 * that turns each red): the upstream links test and the two example tests on the real page. The
 * scratch units and the controls are what show the checks can fail.
 *
 * Residuals the tests cannot see: a new publish.* read outside the panel's lists; a
 * vault.config.json key read through another variable name (parsed.siteTitle, say); the top-level
 * `campaign` key; the panel limits (min, max, 100 entries); and what outputDir and vaultPath do,
 * which is prose.
 */

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');

const gen = require('../scripts/docs-reference');
const textFile = require('../scripts/docs-reference-text');
const { parseFrontmatterText } = require('../src/vault/read');
const { assertScanKeysPresent } = require('../src/cli/check');
const { ConfigError } = require('../src/util/errors');

const ROOT = path.join(__dirname, '..');
const read = (rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8');
const PAGE = 'docs/reference/vault-config.md';
const facts = gen.codeFacts();
const byKey = (block) => Object.fromEntries(facts[block].map((f) => [f.key, f]));

// ---- literal facts the page shows ----

