// ---- units on scratch inputs ----

const SCRATCH = {
  COVERED_PREFIXES: ['publish.alpha', 'publish.beta.gamma'],
  FIELD_SCHEMA: [{ path: 'publish.alpha', kind: 'int', label: 'Alpha label' }, { path: 'publish.delta', kind: 'list', label: 'Delta label' }],
  DISPLAY_PATHS: [{ path: 'publish.beta.gamma', label: 'Gamma label' }],
  PUBLISH_DEFAULTS: { alpha: 3, beta: { gamma: ['x', 'y'] }, toString: 'inherited' },
  scaffoldJson: { one: 'a', two: ['b', 'c'], three: '', four: { k: 1 }, five: true },
  requiredKeys: ['one', 'six'],
  readKeys: ['two', 'seven'],
};

test('vaultFacts gives exact rows for a fake input', () => {
  assert.deepEqual(gen.vaultFacts(SCRATCH), {
    'vault-publish': [
      { key: 'alpha', type: 'whole number', default: '3', panel: 'Alpha label (edit)' },
      { key: 'beta.gamma', default: 'x, y', panel: 'Gamma label (shown)' },
      { key: 'delta', type: 'list of text', panel: 'Delta label (edit)' },
    ],
    'vault-json': [
      { key: 'one', required: 'yes', newCampaigns: 'a' },
      { key: 'two', required: 'no', newCampaigns: 'b, c' },
      { key: 'three', required: 'no' },
      { key: 'four', required: 'no' },
      { key: 'five', required: 'no', newCampaigns: 'true' },
      { key: 'six', required: 'yes' },
      { key: 'seven', required: 'no' },
    ],
  });
});

test('vaultFacts walks only own properties for a default', () => {
  const r = gen.vaultFacts({ ...SCRATCH, COVERED_PREFIXES: ['publish.toString.length'], FIELD_SCHEMA: [], DISPLAY_PATHS: [] });
  assert.deepEqual(r['vault-publish'], [{ key: 'toString.length' }]);
});

test('vaultFacts throws on a path with no publish. prefix', () => {
  assert.throws(() => gen.vaultFacts({ ...SCRATCH, COVERED_PREFIXES: ['theme.palette'] }), /does not start with "publish\."/);
  assert.throws(() => gen.vaultFacts({ ...SCRATCH, DISPLAY_PATHS: [{ path: 'mode', label: 'M' }] }), /does not start with "publish\."/);
});

test('requiredJsonKeys: names from the message, an unrelated error rethrown, no throw gives none', () => {
  assert.deepEqual(gen.requiredJsonKeys(() => { throw new Error('x: p is missing required keys a and b'); }), ['a', 'b']);
  assert.deepEqual(gen.requiredJsonKeys(() => { throw new Error('x: p is missing required key a'); }), ['a']);
  assert.throws(() => gen.requiredJsonKeys(() => { throw new Error('boom'); }), /boom/);
  assert.deepEqual(gen.requiredJsonKeys(() => {}), []);
});

test('requiredJsonKeys on the real validator gives excludeDirs and folderMap', () => {
  assert.deepEqual(gen.requiredJsonKeys(assertScanKeysPresent), ['excludeDirs', 'folderMap']);
  assert.throws(() => assertScanKeysPresent({}, 'f.json', 'c'), (e) => e instanceof ConfigError && /missing required keys excludeDirs and folderMap$/.test(e.message));
});

// ---- the two-way scan of the source for the keys read from vault.config.json ----

const READ_RE = /\b(?:jsonConfig|siteConfig|userJsonConfig)\.([A-Za-z]+)/g;
const scanReadKeys = (sources) => {
  const names = new Set();
  for (const text of sources) for (const m of text.matchAll(READ_RE)) names.add(m[1]);
  return names;
};

function srcFiles() {
  const out = [];
  const walk = (dir) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const p = path.join(dir, entry.name);
      if (entry.isDirectory()) walk(p);
      else if (entry.name.endsWith('.js')) out.push(p);
    }
  };
  walk(path.join(ROOT, 'src'));
  return out;
}

test('control: the scan finds jsonConfig.fooBar and userJsonConfig.qux, and ignores json.index and siteConfigPath.x', () => {
  const found = scanReadKeys(['const a = jsonConfig.fooBar;\nconst b = userJsonConfig.qux;\nconst c = json.index;\nconst d = siteConfigPath.x;']);
  assert.deepEqual([...found].sort(), ['fooBar', 'qux']);
});

test('the keys the source reads from vault.config.json are JSON_READ_KEYS, both ways', () => {
  const scanned = [...scanReadKeys(srcFiles().map((f) => fs.readFileSync(f, 'utf8')))].sort();
  assert.deepEqual(scanned, [...gen.JSON_READ_KEYS].sort(), 'the source reads a vault.config.json key the generator does not list (or the reverse): update JSON_READ_KEYS in scripts/docs-reference.js and add text');
  assert.equal(gen.JSON_READ_KEYS.length, 11);
});

// ---- the page's upstream links ----

test('the two upstream links on the page are built from PIN.json', () => {
  const pin = JSON.parse(read('vendor/gm-apprentice-publish/PIN.json'));
  const page = read(PAGE);
  assert.ok(page.includes(`(${pin.repository}/blob/${pin.labels.tag}/${pin.path}/README.md)`), 'the vault.config.json README link');
  assert.ok(page.includes(`(${pin.repository}/tree/${pin.labels.tag})`), 'the generator documentation link');
  assert.equal(`${pin.repository}/blob/${pin.labels.tag}/${pin.path}/README.md`, 'https://github.com/AntTheLimey/gm-apprentice/blob/publish-v1.14.0/tools/publish/README.md');
});

// ---- the page's examples are valid ----

function leafPaths(value, prefix = '') {
  if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
    const entries = Object.entries(value);
    if (entries.length === 0) return [prefix];
    return entries.flatMap(([k, v]) => leafPaths(v, prefix === '' ? k : `${prefix}.${k}`));
  }
  return [prefix];
}

function unknownPublishPaths(yamlBody) {
  const parsed = parseFrontmatterText('---\n' + yamlBody + '---\n');
  assert.equal(parsed.ok, true, 'the YAML parses');
  const keys = facts['vault-publish'].map((f) => f.key);
  return leafPaths(parsed.data.publish).filter((leaf) => !keys.some((k) => leaf === k || leaf.startsWith(k + '.')));
}

const exampleOf = (lang) => {
  const m = new RegExp('```' + lang + '\\n([\\s\\S]*?)```').exec(read(PAGE));
  assert.ok(m, `the page has a ${lang} example`);
  return m[1];
};

test('the YAML example parses and every key in it is a vault-publish key or sits under one', () => {
  assert.deepEqual(unknownPublishPaths(exampleOf('yaml')), []);
});

test('control: a misspelt key in a YAML example is reported', () => {
  assert.deepEqual(unknownPublishPaths('publish:\n  exclude_feilds: ["a"]\n  mode: player\n'), ['exclude_feilds']);
});

const unknownJsonKeys = (text) => Object.keys(JSON.parse(text)).filter((k) => !(k in byKey('vault-json')));

test('the JSON example parses, passes the required-key check and uses only vault-json keys', () => {
  const text = exampleOf('json');
  assert.doesNotThrow(() => assertScanKeysPresent(JSON.parse(text), 'vault.config.json', 'lease'));
  assert.deepEqual(unknownJsonKeys(text), []);
});

test('control: a misspelt JSON key is reported, and a missing excludeDirs fails the check', () => {
  assert.deepEqual(unknownJsonKeys('{"excludeDirss": [], "folderMap": {}}'), ['excludeDirss']);
  assert.throws(() => assertScanKeysPresent(JSON.parse('{"folderMap": {}}'), 'vault.config.json', 'lease'), /missing required key excludeDirs/);
});

test('the page has the opening, the combining rule, the guarded editor and the backup outside the vault', () => {
  const page = read(PAGE);
  assert.match(page, /^# The vault's publish settings \(vault-config\.md and vault\.config\.json\)\n\nThis page is for someone comfortable editing a text file who/);
  assert.match(page, /\*\*both lists together\*\*/);
  assert.match(page, /guarded/);
  assert.match(page, /backup of the file \*\*outside the\nvault\*\*/);
  assert.match(page, /decisions\/0033-vaultconfig-write-exception\.md/);
  assert.match(page, /decisions\/0041-check-an-edited-copy\.md/);
});

// ---- the examples are safe to copy: dropped into a scratch copy of the sample, check finds nothing new ----

const os = require('os');
const { spawnSync } = require('child_process');

function findingCounts(mutate) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'vault-config-example-'));
  try {
    const vault = path.join(dir, 'v');
    fs.cpSync(path.join(ROOT, 'examples', 'the-long-lease'), vault, { recursive: true });
    mutate({
      vaultConfigMd: path.join(vault, '_meta', 'vault-config.md'),
      vaultConfigJson: path.join(vault, '_meta', 'scriptorium', 'vault.config.json'),
    });
    const config = path.join(dir, 'config.toml');
    fs.writeFileSync(config, `config_version = 1\n\n[campaigns.lease]\nvault = ${JSON.stringify(vault)}\n`);
    const r = spawnSync(process.execPath, [path.join(ROOT, 'bin', 'scriptorium.js'), 'check', 'lease', '--config', config, '--json', '--no-color'], { encoding: 'utf8', maxBuffer: 1 << 28 });
    const counts = {};
    for (const f of JSON.parse(r.stdout).findings) counts[f.id] = (counts[f.id] || 0) + 1;
    return counts;
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

const withYaml = (yamlBody) => ({ vaultConfigMd }) => {
  const s = fs.readFileSync(vaultConfigMd, 'utf8');
  const from = s.indexOf('\npublish:\n');
  const to = s.indexOf('\n---\n', from);
  fs.writeFileSync(vaultConfigMd, s.slice(0, from + 1) + yamlBody.replace(/\n$/, '') + s.slice(to));
};
const withJson = (jsonBody) => ({ vaultConfigJson }) => fs.writeFileSync(vaultConfigJson, jsonBody);

test('the examples dropped into a copy of the sample add no finding to the sample baseline', () => {
  const baseline = findingCounts(() => {});
  assert.deepEqual(findingCounts(withYaml(exampleOf('yaml'))), baseline, 'the YAML example');
  assert.deepEqual(findingCounts(withJson(exampleOf('json'))), baseline, 'the JSON example');
});

test('control: a trimmed exclude list or a short folderMap does add findings', () => {
  const baseline = findingCounts(() => {});
  assert.notDeepEqual(findingCounts(withYaml('publish:\n  exclude_fields: ["secrets"]\n  exclude_dirs: ["_meta", "_Templates"]\n')), baseline);
  assert.notDeepEqual(findingCounts(withJson('{"folderMap": {"Locations": "locations"}, "excludeDirs": ["_meta", "_Templates"]}')), baseline);
});
